// Fake of @minecraft/server for tests: a block world with hills, trees and a
// pond, enough of the API for main.js and site.js. It proves logic, not looks.
import { CATALOG } from "../../../behavior_pack/scripts/catalog.js";

export const log = [], subs = {};
const ev = (n) => ({ subscribe: (f) => (subs[n] = f) });
export const StructureRotation = { None: "None", Rotate90: "Rotate90", Rotate180: "Rotate180", Rotate270: "Rotate270" };
export const StructureSaveMode = { Memory: "Memory" };
export class ItemStack { constructor(t) { this.typeId = t; } }
export class BlockPermutation {
  constructor(type, states) { this.type = type; this.states = states; }
  static resolve(type, states) { return new BlockPermutation(type, states); }
}

// Test knobs.
export const fake = {
  clockwise: true, // false: the game's Rotate90 turns the other way from the planner's
  ground: (x, z) => 70 + Math.round(6 * Math.sin(x / 25) + 5 * Math.cos(z / 30)),
  pond: (x, z) => (x - 40) ** 2 + (z + 30) ** 2 < 15 ** 2,
  tree: (x, z) => (x * 7 + z * 13) % 37 === 0,
};
const WATER_LEVEL = 68;
const blocks = new Map();
const key = (x, y, z) => x + "," + y + "," + z;

function natural(x, y, z) {
  if (fake.pond(x, z)) return y <= 60 ? "minecraft:stone" : y <= WATER_LEVEL ? "minecraft:water" : "minecraft:air";
  const g = fake.ground(x, z);
  if (y < g) return "minecraft:dirt";
  if (y === g) return "minecraft:grass_block";
  if (fake.tree(x, z)) return y <= g + 4 ? "minecraft:oak_log" : y <= g + 6 ? "minecraft:oak_leaves" : "minecraft:air";
  return y === g + 1 && (x + z) % 5 === 0 ? "minecraft:short_grass" : "minecraft:air";
}
export const typeAt = (x, y, z) => blocks.get(key(x, y, z)) ?? natural(x, y, z);
export const reset = () => { blocks.clear(); log.length = 0; };

class Block {
  constructor(x, y, z) { this.x = x; this.y = y; this.z = z; }
  get typeId() { return typeAt(this.x, this.y, this.z); }
  get isAir() { return this.typeId === "minecraft:air"; }
  below() { return this.y > -64 ? new Block(this.x, this.y - 1, this.z) : undefined; }
  above() { return this.y < 319 ? new Block(this.x, this.y + 1, this.z) : undefined; }
  setType(t) { blocks.set(key(this.x, this.y, this.z), t); }
}

export const dimension = {
  heightRange: { min: -64, max: 320 },
  getBlock: ({ x, y, z }) => new Block(x, y, z),
  getTopmostBlock({ x, z }) {
    for (let y = 319; y >= -64; y--) if (typeAt(x, y, z) !== "minecraft:air") return new Block(x, y, z);
  },
  setBlockType({ x, y, z }, t) { blocks.set(key(x, y, z), t); },
  setBlockPermutation({ x, y, z }, p) { blocks.set(key(x, y, z), p.type); },
  runCommand(c) { log.push(["command", c]); return { successCount: 1 }; },
  spawnEntity(type, at) { log.push(["spawn", type, at]); },
};

const QUARTER = { None: 0, Rotate90: 1, Rotate180: 2, Rotate270: 3 };
const CALIB = { "minecraft:gold_block": [0, 0], "minecraft:iron_block": [2, 0], "minecraft:diamond_block": [0, 1] };
const turn = ([x, z], r) => [[x, z], [-z, x], [-x, -z], [z, -x]][r];

const timers = [];
export const system = {
  currentTick: 0,
  run: (f) => f(),
  runTimeout: (f) => timers.push(f),
  // Run queued timers (and whatever they queue) until none are left.
  async flush() {
    for (let quiet = 0; quiet < 3;) {
      await new Promise((r) => setImmediate(r));
      if (timers.length) { quiet = 0; system.currentTick++; timers.splice(0).forEach((f) => f()); } else quiet++;
    }
  },
  afterEvents: { scriptEventReceive: ev("script") },
};

export const world = {
  structureManager: {
    delete() {},
    createFromWorld: (...a) => log.push(["save", a[0]]),
    place(id, dim, at, o) {
      const rot = o?.rotation ?? "None";
      let r = QUARTER[rot];
      if (!fake.clockwise) r = (4 - r) % 4;
      if (id === "bs:calib") {
        const far = turn([2, 1], r), shift = [Math.max(0, -far[0]), Math.max(0, -far[1])];
        for (const [type, local] of Object.entries(CALIB)) {
          const q = turn(local, r);
          blocks.set(key(at.x + q[0] + shift[0], at.y, at.z + q[1] + shift[1]), type);
        }
        return;
      }
      const name = id.slice(3), size = CATALOG[name];
      if (!size) throw new Error("no structure " + id);
      const [w, d] = r % 2 ? [size[2], size[0]] : [size[0], size[2]];
      for (let x = 0; x < w; x++) for (let z = 0; z < d; z++) for (let y = 0; y < size[1]; y++) blocks.set(key(at.x + x, at.y + y, at.z + z), "placed:" + name);
      log.push(["place", id, at, rot]);
    },
  },
  afterEvents: { itemUse: ev("use"), playerSpawn: ev("spawn") },
  beforeEvents: { playerInteractWithBlock: ev("tap") },
};
